/**
 * A URL slug: lowercase ASCII letters and digits separated by single hyphens.
 * Accents are dropped ("Café" -> "cafe"); anything else separates words.
 *
 * Options:
 *   maxLength - if given, the slug is at most this many characters long.
 *               It never ends with a hyphen. It is cut at a word boundary
 *               when possible. A single word longer than maxLength is cut
 *               mid-word.
 */
export function slugify(text, options = {}) {
  const slug = text
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

  const maxLength = options == null ? undefined : options.maxLength;
  if (maxLength == null || slug.length <= maxLength) {
    return slug;
  }
  if (!(maxLength > 0)) {
    return "";
  }

  const limit = Math.floor(maxLength);
  let cut = slug.slice(0, limit);
  if (slug[limit] !== "-") {
    // The cut falls inside a word; back up to the last word boundary if any.
    const lastHyphen = cut.lastIndexOf("-");
    if (lastHyphen > 0) {
      cut = cut.slice(0, lastHyphen);
    }
  }
  return cut.replace(/-+$/g, "");
}
